            $actorModel = $actor->id === null ? null : ($actor->type === $request->subject()->type() && $actor->id === $request->subject()->id() ? $subject : $this->resolver->resolve($panel, SubjectRef::of($actor->type, $actor->id)));
60→        } catch (Throwable $caught) {
