    /** @return array{PanelCatalog, EvaluationFrame} */
    private function dynamicAttempt(PanelCatalog $static, AccessRequest $request, EvaluationFrame $initial): array
    {
        $sources = PanelSources::of($this->registry->recipe($initial->panel()->id()), $this->container)->all();
        for ($attempt = 0; $attempt < 3; $attempt++) {
            // Every attempt starts with the original static catalog and frame; no previous overlay/state survives.
            $frame = $initial;
            $sessions = $states = $definitions = $contributions = [];
            foreach ($sources as ['source' => $source]) {
110→                if ($source instanceof DatabaseSource) {
