        $catalog = $static;

        try {
            foreach ($sources as ['source' => $source]) {
                if (! $source instanceof ProvidesPermissions || ! $source->isDynamic()) {
                    continue;
                }
                $items = $source instanceof DatabaseSource
                    ? $source->readPermissions($sessions[$source->id()], $frame->panel(), $frame->scope()->tenant)
                    : $source->permissions($frame->panel(), $frame->scope()->tenant);
                foreach (PanelCatalog::untrusted($items) as $item) {
                    $definitions[] = $item;
                }
            }
            $catalog = $static->withDynamic($definitions);

            if ($catalog->has($request->permission())) {
                foreach ($sources as ['source' => $source]) {
                    if ($source instanceof FolderSource) {
                        $source->bindRoleClasses(array_column($catalog->roles(), 'class'));
                    }

                    if ($source instanceof DatabaseSource) {
                        $snapshot = $source->readAssignments($sessions[$source->id()], $request->subject(), [$frame->scope()], $frame);
                        $items = [...$snapshot['grants'], ...$snapshot['roles']];
                    } else {
                        $items = [];

                        if ($source instanceof ProvidesGrants) {
                            foreach (PanelCatalog::untrusted($source->grants($request->subject(), [$frame->scope()], $frame)) as $item) {
                                if (! $item instanceof Grant) {
                                    throw new InvalidSourceContributionException('Unexpected direct grant contribution type.');
                                }
                                $items[] = $item;
                            }
                        }

                        if ($source instanceof ProvidesRoleGrants) {
                            foreach (PanelCatalog::untrusted($source->roleGrants($request->subject(), [$frame->scope()], $frame)) as $item) {
                                if (! $item instanceof RoleContribution) {
                                    throw new InvalidSourceContributionException('Unexpected role contribution type.');
                                }
                                $items[] = $item;
                            }
                        }
                    }
                    foreach ($items as $item) {
                        $contributions[] = [$source, $item];
                    }
                }
            }
        } catch (Throwable $caught) {
            $error = $caught;
        }
        $stable = true;
        foreach ($sources as ['source' => $source]) {
            if (! $source instanceof FencesReads || ! isset($states[$source->id()])) {
                continue;
            }
            $after = $source instanceof DatabaseSource ? $source->readState($sessions[$source->id()], $initial)
                : $source->state($initial->panel(), $initial->scope()->tenant);
            $stable = $states[$source->id()]->equals($after) && $stable;
        }

        if (! $stable) {
            continue;
        }

        if ($error !== null) {
            throw $error;
        }
        foreach ($sources as ['source' => $source]) {
            if ($source instanceof DatabaseSource) {
                $frame = $frame->withState($states[$source->id()]);
            }
        }

        return [$catalog, $frame->withPreparedContributions($contributions, $states)];
    }

    throw new ConsistencyException('Dynamic Prepare/authority changed during all three read attempts.');
}
